```javascript
const axios = require("axios");

async function sendAiRequest(message, sessionId, csrfToken) {
  try {
    const response = await axios.post(
      "https://autoresbot.com/api/ai-chat",
      {
        message: message,
        sessionId: sessionId,
        _csrf: csrfToken
      },
      {
        headers: {
          "Content-Type": "application/json",
          "X-Requested-With": "XMLHttpRequest",
          "CSRF-Token": csrfToken
        }
      }
    );
    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

const message = "Apa itu REST API?";
const sessionId = "website:msqsi1mcx3jnax";
const csrfToken = "XowrqZ6F-_maI7hnqgNd2IcRaK0zA9c2LuHI";

sendAiRequest(message, sessionId, csrfToken)
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
